quantities.raw:
{
  "relationship": {
    "statement": "A decision tree classifies samples by recursively splitting data along feature thresholds that maximize impurity reduction. Each branch routes points to child nodes until regions are pure enough to predict a majority class.",
    "formula": "\\Delta G = G_0 - \\left(\\frac{N_L}{N}G_L + \\frac{N_R}{N}G_R\\right)",
    "assumptions": [
      "Binary classification (Class A vs. Class B) using axis-aligned threshold splits.",
      "Node impurity is measured by Gini impurity, G = 1 - p_A^2 - p_B^2.",
      "Dataset size is fixed at N = 20 samples across two features."
    ]
  },
  "quantities": [
    {
      "id": "split_x",
      "label": "Root split x",
      "unit": "",
      "role": "control",
      "meaning": "Threshold on feature x used at the root node to send samples left or right."
    },
    {
      "id": "split_y",
      "label": "Child split y",
      "unit": "",
      "role": "control",
      "meaning": "Second-level threshold on feature y applied to refine a mixed child node."
    },
    {
      "id": "separation",
      "label": "Class separation",
      "unit": "",
      "role": "control",
      "meaning": "Distance between the two class clusters in feature space."
    },
    {
      "id": "total_samples",
      "label": "Total samples N",
      "unit": "pts",
      "role": "fixed",
      "meaning": "Total number of labeled training samples evaluated at the root node."
    },
    {
      "id": "parent_gini",
      "label": "Parent Gini G_0",
      "unit": "",
      "role": "result",
      "meaning": "Gini impurity of the unsplit root node before applying any threshold."
    },
    {
      "id": "weighted_gini",
      "label": "Weighted child Gini",
      "unit": "",
      "role": "result",
      "meaning": "Size-weighted average Gini impurity of the left and right root branches."
    },
    {
      "id": "gini_gain",
      "label": "Impurity reduction",
      "unit": "",
      "role": "result",
      "meaning": "Drop in Gini impurity achieved by the root split (G_0 minus weighted child Gini)."
    },
    {
      "id": "left_count",
      "label": "Left branch count",
      "unit": "pts",
      "role": "result",
      "meaning": "Number of samples satisfying x <= split_x routed to the left branch."
    },
    {
      "id": "right_count",
      "label": "Right branch count",
      "unit": "pts",
      "role": "result",
      "meaning": "Number of samples satisfying x > split_x routed to the right branch."
    },
    {
      "id": "accuracy",
      "label": "Tree accuracy",
      "unit": "%",
      "role": "result",
      "meaning": "Percentage of samples correctly classified by majority vote at the leaves."
    }
  ]
}

